"""Shared helpers for the Ukiyo-e verification suite."""

import hashlib
import os
import re
import shutil
import subprocess
import sys
import tempfile
import tomllib
from dataclasses import dataclass
from pathlib import Path

sys.dont_write_bytecode = True

REPO = Path(__file__).resolve().parents[1]
GENERATED_PATHS = (
    "lua/ukiyo_e/palette.lua",
    "tmux/colors.conf",
    "tmux/status.conf",
    "tmux/status-plain.conf",
    "gnome-terminal/palette.sh",
)
HEADER_LUA = (
    "-- GENERATED by scripts/generate.py from palette.toml."
    " Do not edit by hand."
)
HEADER_SH = (
    "# GENERATED by scripts/generate.py from palette.toml."
    " Do not edit by hand."
)
SEED_HASH = "bb85e4bfc8d89b0e62c8fa53ccdd13d12e2f77b3"
IGNORED_COPY = shutil.ignore_patterns(".git", "__pycache__")


@dataclass(frozen=True)
class RunResult:
    """Exit code and captured text of one finished process."""

    code: int
    stdout: str
    stderr: str


def run(argv, cwd=None, env=None, stdin=None):
    """Run a command and capture its text output."""
    proc = subprocess.run(
        argv,
        cwd=cwd,
        env=env,
        input=stdin,
        capture_output=True,
        text=True,
        check=False,
    )
    return RunResult(proc.returncode, proc.stdout, proc.stderr)


def scratch_dir():
    """Create a fresh directory under TMPDIR (the session scratchpad)."""
    return Path(tempfile.mkdtemp(prefix="ukiyo_e_"))


def copy_repo():
    """Copy the working tree (without .git) into a scratch directory."""
    target = scratch_dir() / "repo"
    shutil.copytree(REPO, target, ignore=IGNORED_COPY, symlinks=True)
    return target


def remove_tree(path):
    """Delete a scratch tree created by this suite."""
    shutil.rmtree(Path(path).parent, ignore_errors=True)


def remove_dir(path):
    """Delete a scratch directory created by scratch_dir()."""
    shutil.rmtree(path, ignore_errors=True)


def generate(root, *args):
    """Run the generator of a repository copy."""
    script = Path(root) / "scripts" / "generate.py"
    return run([sys.executable, str(script), *args], cwd=root)


def generated_hashes(root):
    """Map every generated path to the SHA-256 of its bytes."""
    hashes = {}
    for rel in GENERATED_PATHS:
        data = (Path(root) / rel).read_bytes()
        hashes[rel] = hashlib.sha256(data).hexdigest()
    return hashes


def load_palette_toml(root=REPO):
    """Parse palette.toml of a repository tree."""
    with open(Path(root) / "palette.toml", "rb") as handle:
        return tomllib.load(handle)


def resolve_ref(doc, value):
    """Resolve a [terminal]/[tmux] value to lowercase hex."""
    if value.startswith("#"):
        return value.lower()
    return doc["palette"][value].lower()


def resolved_ansi(root=REPO):
    """The 16 resolved [terminal].ansi colours."""
    doc = load_palette_toml(root)
    return [resolve_ref(doc, v) for v in doc["terminal"]["ansi"]]


def resolved_tmux(root=REPO):
    """Every [tmux] role resolved to lowercase hex."""
    doc = load_palette_toml(root)
    return {k: resolve_ref(doc, v) for k, v in doc["tmux"].items()}


def replace_line(path, prefix, new_line):
    """Replace the unique line of a file that starts with prefix."""
    lines = Path(path).read_text().split("\n")
    hits = [i for i, line in enumerate(lines) if line.startswith(prefix)]
    if len(hits) != 1:
        raise AssertionError(f"{prefix!r}: {len(hits)} matching lines")
    lines[hits[0]] = new_line
    Path(path).write_text("\n".join(lines))


def set_ansi(root, entries):
    """Rewrite the [terminal].ansi array of a copy's palette.toml."""
    path = Path(root) / "palette.toml"
    body = ", ".join(f'"{e}"' for e in entries)
    text = re.sub(
        r"(?ms)^ansi\s*=\s*\[.*?\]",
        lambda _m: f"ansi = [{body}]",
        path.read_text(),
    )
    path.write_text(text)


def set_ansi_entry(root, index, value):
    """Change one [terminal].ansi entry of a copy's palette.toml."""
    entries = list(load_palette_toml(root)["terminal"]["ansi"])
    entries[index] = value
    set_ansi(root, entries)


def real_dconf_dump():
    """Read-only dump of the user's real GNOME Terminal settings."""
    return run(["dconf", "dump", "/org/gnome/terminal/"]).stdout


