_SERVER_COUNT = [0]


@dataclass(frozen=True)
class TmuxServer:
    """An isolated tmux server on a dedicated -L socket."""

    name: str
    config: Path

    @classmethod
    def start(cls, case):
        """Start a server for a TestCase; kill it on cleanup."""
        _SERVER_COUNT[0] += 1
        name = f"ukiyo_e_test_{os.getpid()}_{_SERVER_COUNT[0]}"
        folder = scratch_dir()
        config = folder / "empty.conf"
        config.write_text("")
        server = cls(name, config)
        case.addCleanup(remove_dir, folder)
        result = server.tmux("new-session", "-d", "-x", "200", "-y", "50")
        if result.code != 0:
            raise AssertionError(f"tmux did not start: {result.stderr}")
        socket = Path(server.tmux("display", "-p", "#{socket_path}")
                      .stdout.strip())
        case.addCleanup(socket.unlink, missing_ok=True)
        case.addCleanup(server.tmux, "kill-server")
        return server

    def tmux(self, *args):
        argv = ["tmux", "-L", self.name, "-f", str(self.config), *args]
        return run(argv, stdin="")

    def value(self, option):
        result = self.tmux("show-options", "-gqv", option)
        return result.stdout.rstrip("\n")

    def run_theme(self, root=REPO):
        """Run ukiyo_e.tmux the way TPM does, against this server."""
        where = self.tmux("display", "-p", "#{socket_path},#{pid}")
        env = dict(os.environ, TMUX=f"{where.stdout.strip()},0")
        return run([str(Path(root) / "ukiyo_e.tmux")], env=env, stdin="")

    def snapshot(self):
        """Global options, window options, and non-option state."""
        return {
            "options": self._options("-g"),
            "window": self._options("-gw"),
            "server": self._options("-s"),
            "keys": self.tmux("list-keys").stdout,
            "hooks": self.tmux("show-hooks", "-g").stdout,
            "environment": self.tmux("show-environment", "-g").stdout,
        }

    def _options(self, scope):
        lines = self.tmux("show-options", scope).stdout.splitlines()
        return dict(line.split(" ", 1) if " " in line else (line, "")
                    for line in lines)


def changed_options(before, after):
    """Option names whose global value differs between snapshots."""
    changed = set()
    for table in ("options", "window", "server"):
        old, new = before[table], after[table]
        changed |= {k for k in set(old) | set(new)
                    if old.get(k) != new.get(k)}
    return changed


GNOME_HARNESS = REPO / "tests" / "gnome_harness.py"


def run_gnome_harness(scenario, root=REPO):
    """Run a harness scenario in a private D-Bus session and dconf db."""
    folder = scratch_dir()
    runtime = folder / "runtime"
    runtime.mkdir(mode=0o700)
    env = dict(os.environ, XDG_CONFIG_HOME=str(folder / "config"),
               XDG_RUNTIME_DIR=str(runtime),
               UKIYO_E_OUTER_BUS=os.environ.get("DBUS_SESSION_BUS_ADDRESS",
                                                ""))
    env.pop("DBUS_SESSION_BUS_ADDRESS", None)
    argv = ["dbus-run-session", "--", sys.executable, str(GNOME_HARNESS),
            scenario, str(root)]
    try:
        result = run(argv, env=env)
    finally:
        remove_dir(folder)
    return result


def parse_dump(text):
    """dconf dump text -> {section: {key: value}}."""
    sections, current = {}, None
    for line in text.splitlines():
        if line.startswith("[") and line.endswith("]"):
            current = sections.setdefault(line[1:-1], {})
        elif "=" in line and current is not None:
            key, value = line.split("=", 1)
            current[key] = value
    return sections


class RealDconfGuard:
    """Fail loudly if the user's real GNOME Terminal settings change."""

    before = None

    @classmethod
    def take(cls):
        cls.before = real_dconf_dump()

    @classmethod
    def verify(cls):
        after = real_dconf_dump()
        if after != cls.before:
            raise AssertionError("REAL DCONF CHANGED")
